CREATE TABLE IF NOT EXISTS article_topics (slug text PRIMARY KEY, name text NOT NULL UNIQUE CHECK (length(name) BETWEEN 1 AND 60), definition text NOT NULL CHECK (length(definition) BETWEEN 1 AND 2000), group_key text NOT NULL CHECK (group_key IN ('company','field','genre')), tags text[] NOT NULL CHECK (cardinality(tags)>0), position integer NOT NULL DEFAULT 2147483647, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
